import {on} from 'delegated-events'
import {updateSearchParams} from '@github-ui/history'

on('click', '#clear-github-ui-sha', function () {
  // clear _ui_sha cookie and query param and reload the page
  const url = new URL(window.location.href, window.location.origin)
  url.searchParams.delete('_ui_sha')
  url.searchParams.set('_clear_ui_sha', 'true')
  updateSearchParams(url.searchParams)
  window.location.reload()
})
