// Use a try/catch instead of feature detecting `layout-shift`
// support, since some browsers throw when using the new `type` option.
// https://bugs.webkit.org/show_bug.cgi?id=209216
try {
  const params = new URLSearchParams(document.location.search.substring(1))
  if (params.get('cls')) {
    const po = new PerformanceObserver(list => {
      let i = 0
      for (const entry of list.getEntries()) {
        // @ts-expect-error LayoutShift doesn't exist in TS yet.
        if (entry.hadRecentInput) {
          continue
        }
        // @ts-expect-error LayoutShift doesn't exist in TS yet.
        for (const source of entry.sources as LayoutShiftAttribution[]) {
          if (
            source.node?.nodeType === Node.ELEMENT_NODE &&
            (source.node as Element).getAttribute('data-type') === 'layout-shift'
          ) {
            // If the node already has a data-type attribute, skip it.
            continue
          }
          // eslint-disable-next-line no-console
          console.log('The following node was shifted unexpectingly')
          // eslint-disable-next-line no-console
          console.log(source.node)

          const color = [
            '0.4 0.2 335',
            '0.5 0.2   5',
            '0.6 0.2  20',
            '0.7 0.2  60',
            '0.9 0.2 100',
            '0.8 0.2 130',
            '0.8 0.2 150',
            '0.7 0.2 180',
            '0.7 0.2 200',
            '0.6 0.2 230',
            '0.5 0.2 260',
            '0.4 0.2 300',
          ][i++ % 12]

          const box = document.createElement('div')
          box.setAttribute('data-type', 'layout-shift')
          box.style.transition = 'all 0.5s ease-in-out'
          box.style.position = 'absolute'
          box.style.left = `${source.previousRect.left / devicePixelRatio}px`
          box.style.top = `${source.previousRect.top / devicePixelRatio}px`
          box.style.width = `${source.previousRect.width / devicePixelRatio}px`
          box.style.height = `${source.previousRect.height / devicePixelRatio}px`
          box.style.zIndex = '100000'
          box.style.pointerEvents = 'none'
          box.style.border = `1px solid oklch(${color})`
          box.style.boxSizing = 'border-box'
          document.body.appendChild(box)

          setTimeout(function () {
            box.style.left = `${source.currentRect.left / devicePixelRatio}px`
            box.style.top = `${source.currentRect.top / devicePixelRatio}px`
            box.style.width = `${source.currentRect.width / devicePixelRatio}px`
            box.style.height = `${source.currentRect.height / devicePixelRatio}px`
          }, 2500)

          setTimeout(function () {
            box.remove()
          }, 5000)
        }
      }
    })

    po.observe({type: 'layout-shift', buffered: true})
  }
} catch {
  // Do nothing if the browser doesn't support this API.
}
